  "userQuery": "弄个物流卡片,显示距离8公里,能打电话,读天气,显示已签收",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToCallPhone",
      "args": {
        "phoneNumber": "95338"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "logistics": {
        "distanceText": {
          "type": "string",
          "description": "快递当前位置与用户的距离展示文本",
          "sampleValue": "8公里"
        },
        "statusText": {
          "type": "string",
          "description": "快递当前签收状态",
          "sampleValue": "已签收"
        },
        "statusDetail": {
          "type": "string",
          "description": "快递签收结果的短说明",
          "sampleValue": "包裹已签收"
        }
      },
      "weather": {
        "current": {
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          },
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "彩色快递箱图标，适合用于物流信息、包裹状态和取件提醒的视觉识别。"
    }
  ]
}

